WITH latest AS (SELECT id, opened_date FROM accounts QUALIFY ROW_NUMBER() OVER (PARTITION BY account_type, customer_id ORDER BY opened_date DESC NULLS FIRST, id) = 1) SELECT DATE_TRUNC('YEAR', opened_date) AS year_start, DATE_TRUNC('MONTH', opened_date) AS activity_month, COUNT(*) AS num_rows, COUNT(*) AS cnt, COUNT(*) AS row_count, COUNT(DISTINCT id) AS distinct_ids, GROUPING_ID() AS grouping_id FROM latest GROUP BY ROLLUP (DATE_TRUNC('YEAR', opened_date), DATE_TRUNC('MONTH', opened_date)) ORDER BY row_count DESC NULLS LAST
